3	import React, { useState, useMemo } from 'react';
4	import { ModalContainer } from '../../../components/shared/ModalContainer';
5	import { SharedButton } from '../../../components/shared/SharedButton';
6	import { saveCustomPlaylist, deleteCustomPlaylist } from '../services/engine';
7	import { useVinylStore } from '../store/useVinylStore';
8	import type { CustomPlaylist, ChannelOriginItem } from '../types';
9	import {
10	  Crown,
11	  Plus,
12	  Trash2,
13	  Edit3,
14	  Search,
15	  Check,
16	  CheckSquare,
17	  Square,
18	  Layers,
19	  Radio,
20	  Sparkles,
21	  ArrowLeft,
22	} from 'lucide-react';
23	
24	interface PlaylistManagerModalProps {
25	  isOpen: boolean;
26	  onClose: () => void;
27	  projectId: string;
28	  channelList: ChannelOriginItem[];
29	  onSelectPlaylist?: (playlistId: string) => void;
30	  initialEditPlaylistId?: string | null;
31	}
32	
33	const PRESET_EMOJIS = ['🎵', '🎧', '⚔️', '🌙', '⚡', '🚀', '🌊', '🪶', '☕', '🔥', '💎', '🌸', '🌌', '👑'];
34	
35	const TIMEBLOCK_OPTIONS = [
36	  { id: 'Arc Zero ~ Kick Starter', label: 'Arc Zero ~ Kick Starter', emoji: '🌊' },
37	  { id: 'Arc 01 ~ Morning Star - Raye', label: 'Arc 01 ~ Morning Star - Raye', emoji: '🚀' },
38	  { id: 'Arc 02 ~ Battle Phase - Racheal', label: 'Arc 02 ~ Battle Phase - Racheal', emoji: '⚔️' },
39	  { id: 'Arc 03 ~ Night Hours Melody', label: 'Arc 03 ~ Night Hours Melody', emoji: '🌙' },
40	  { id: 'Arc 04 ~ Sacred Pragma', label: 'Arc 04 ~ Sacred Pragma', emoji: '🪶' },
41	];
42	
43	export const PlaylistManagerModal: React.FC<PlaylistManagerModalProps> = ({
44	  isOpen,
45	  onClose,
46	  projectId,
47	  channelList,
48	  onSelectPlaylist,
49	  initialEditPlaylistId = null,
50	}) => {
51	  const { customPlaylists, addCustomPlaylist, updateCustomPlaylist, removeCustomPlaylist } =
52	    useVinylStore();
53	
54	  const [mode, setMode] = useState<'list' | 'edit'>(initialEditPlaylistId ? 'edit' : 'list');
55	  const [editingPlaylistId, setEditingPlaylistId] = useState<string | null>(initialEditPlaylistId);
56	
57	  // Form fields
58	  const [name, setName] = useState('');
59	  const [emoji, setEmoji] = useState('🎵');
60	  const [description, setDescription] = useState('');
61	  const [selectedChannels, setSelectedChannels] = useState<string[]>([]);
62	  const [selectedTimeblocks, setSelectedTimeblocks] = useState<string[]>([]);
63	  const [channelSearchQuery, setChannelSearchQuery] = useState('');
64	  const [isSaving, setIsSaving] = useState(false);
65	  const [errorMessage, setErrorMessage] = useState<string | null>(null);
66	
67	  const startCreating = () => {
68	    setEditingPlaylistId(null);
69	    setName('');
70	    setEmoji('🎵');
71	    setDescription('');
72	    setSelectedChannels([]);
73	    setSelectedTimeblocks([]);
74	    setChannelSearchQuery('');
75	    setErrorMessage(null);
76	    setMode('edit');
77	  };
78	
79	  const startEditing = (pl: CustomPlaylist) => {
80	    setEditingPlaylistId(pl.id);
81	    setName(pl.name);
82	    setEmoji(pl.emoji || '🎵');
83	    setDescription(pl.description || '');
84	    setSelectedChannels([...pl.channels]);
85	    setSelectedTimeblocks([...(pl.compatible_timeblocks || [])]);
86	    setChannelSearchQuery('');
87	    setErrorMessage(null);
88	    setMode('edit');
89	  };
90	
91	  const toggleChannel = (chName: string) => {
92	    setSelectedChannels((prev) =>
93	      prev.includes(chName) ? prev.filter((c) => c !== chName) : [...prev, chName]
94	    );
95	  };
96	
97	  const toggleTimeblock = (tbId: string) => {
98	    setSelectedTimeblocks((prev) =>
99	      prev.includes(tbId) ? prev.filter((t) => t !== tbId) : [...prev, tbId]
100	    );
101	  };
102	
103	  const filteredChannels = useMemo(() => {
104	    if (!channelSearchQuery.trim()) return channelList;
105	    const q = channelSearchQuery.toLowerCase().trim();
106	    return channelList.filter((ch) => ch.name.toLowerCase().includes(q));
107	  }, [channelList, channelSearchQuery]);
108	
109	  const totalTracksInSelection = useMemo(() => {
110	    const chSet = new Set(selectedChannels);
111	    return channelList
112	      .filter((ch) => chSet.has(ch.name))
113	      .reduce((sum, ch) => sum + ch.count, 0);
114	  }, [channelList, selectedChannels]);
115	
116	  const handleSave = async () => {
117	    if (!name.trim()) {
118	      setErrorMessage('Playlist title is required');
119	      return;
120	    }
121	    if (selectedChannels.length === 0) {
122	      setErrorMessage('Please select at least one channel for this playlist');
123	      return;
124	    }
125	
126	    setIsSaving(true);
127	    setErrorMessage(null);
128	
129	    try {
130	      const saved = await saveCustomPlaylist(projectId, {
131	        id: editingPlaylistId || undefined,
132	        name: name.trim(),
133	        emoji,
134	        description: description.trim(),
135	        channels: selectedChannels,
136	        compatible_timeblocks: selectedTimeblocks,
137	      });
138	
139	      if (editingPlaylistId) {
140	        updateCustomPlaylist(saved);
141	      } else {
142	        addCustomPlaylist(saved);
143	      }
144	
145	      setMode('list');
146	      if (onSelectPlaylist) {
147	        onSelectPlaylist(saved.id);
148	      }
149	    } catch (err: any) {
150	      setErrorMessage(err.message || 'Failed to save playlist');
151	    } finally {
152	      setIsSaving(false);
153	    }
154	  };
155	
156	  const handleDelete = async (plId: string) => {
157	    if (!confirm('Are you sure you want to delete this custom playlist?')) return;
158	    try {
159	      await deleteCustomPlaylist(projectId, plId);
160	      removeCustomPlaylist(plId);
161	      if (mode === 'edit' && editingPlaylistId === plId) {
162	        setMode('list');
163	      }
164	    } catch (err) {
165	      console.error('Failed to delete playlist:', err);
166	    }
167	  };
168	
169	  return (
170	    <ModalContainer
171	      isOpen={isOpen}
172	      onClose={onClose}
173	      title={mode === 'list' ? 'Custom Playlists' : editingPlaylistId ? 'Edit Playlist' : 'New Playlist'}
174	      subtitle={
175	        mode === 'list'
176	          ? 'Federate multiple channels into thematic listening streams'
177	          : 'Combine channels under a shared musical style and timeblock'
178	      }
179	      icon={<Crown className="w-5 h-5 text-[#ffd86b]" />}
180	      maxWidth="xl"
181	    >
182	      {mode === 'list' ? (
183	        <div className="space-y-4 text-left">
184	          {/* Top Action */}
185	          <div className="flex items-center justify-between">
186	            <span className="text-xs font-mono text-[#8c7a9e]">
187	              Active Playlists ({customPlaylists.length})
188	            </span>
189	            <SharedButton variant="primary" size="sm" onClick={startCreating} className="flex items-center gap-1.5">
190	              <Plus className="w-3.5 h-3.5 text-black" />
191	              <span>New Playlist</span>
192	            </SharedButton>
193	          </div>
194	
195	          {/* List of Playlists */}
196	          {customPlaylists.length === 0 ? (
197	            <div className="p-8 rounded-xl bg-[#140f1c] border border-[#2b2238] text-center space-y-2">
198	              <Sparkles className="w-8 h-8 text-[#ffd86b] mx-auto opacity-70" />
199	              <p className="text-sm font-cinzel font-bold text-[#f5f0e8]">No Custom Playlists Yet</p>
200	              <p className="text-xs text-[#8c7a9e] max-w-sm mx-auto">
201	                Group your favorite channels together (e.g., HOYO-MiX + NCS) to create themed listening streams.
202	              </p>
203	            </div>
204	          ) : (
205	            <div className="space-y-2 max-h-[360px] overflow-y-auto pr-1">
206	              {customPlaylists.map((pl) => {
207	                const pooledTracks = channelList
208	                  .filter((ch) => pl.channels.includes(ch.name))
209	                  .reduce((sum, ch) => sum + ch.count, 0);
210	
211	                return (
212	                  <div
213	                    key={pl.id}
214	                    className="p-3.5 rounded-xl bg-[#15101f] hover:bg-[#1c152a] border border-[#2e243d] hover:border-[#d4af37]/60 transition flex items-center justify-between gap-3 group"
215	                  >
216	                    <div
217	                      className="flex items-center gap-3 cursor-pointer flex-1 min-w-0"
218	                      onClick={() => {
219	                        if (onSelectPlaylist) {
220	                          onSelectPlaylist(pl.id);
221	                          onClose();
222	                        }
223	                      }}
224	                    >
225	                      <span className="text-2xl flex-shrink-0">{pl.emoji || '🎵'}</span>
226	                      <div className="truncate">
227	                        <h4 className="text-sm font-bold text-white group-hover:text-[#ffd86b] transition truncate">
228	                          {pl.name}
229	                        </h4>
230	                        <p className="text-[11px] font-mono text-[#8c7a9e] truncate">
231	                          {pl.channels.length} channel{pl.channels.length > 1 ? 's' : ''} •{' '}
232	                          <span className="text-[#ffd86b] font-bold">{pooledTracks.toLocaleString()}</span> songs
233	                          {pl.description ? ` • ${pl.description}` : ''}
234	                        </p>
235	                      </div>
236	                    </div>
237	
238	                    <div className="flex items-center gap-1.5 flex-shrink-0">
239	                      <button
240	                        type="button"
241	                        onClick={() => startEditing(pl)}
242	                        title="Edit Playlist Channels"
243	                        className="p-1.5 rounded-lg bg-[#20172e] hover:bg-[#2e2042] text-[#8c7a9e] hover:text-white border border-[#3b2b52] transition cursor-pointer"
244	                      >
245	                        <Edit3 className="w-3.5 h-3.5" />
246	                      </button>
247	                      <button
248	                        type="button"
249	                        onClick={() => handleDelete(pl.id)}
250	                        title="Delete Playlist"
251	                        className="p-1.5 rounded-lg bg-rose-950/40 hover:bg-rose-900/60 text-rose-300 hover:text-rose-100 border border-rose-800/50 transition cursor-pointer"
252	                      >
253	                        <Trash2 className="w-3.5 h-3.5" />
254	                      </button>
255	                    </div>
256	                  </div>
257	                );
258	              })}
259	            </div>
260	          )}
261	        </div>
262	      ) : (
263	        /* Edit / Create Form */
264	        <div className="space-y-4 text-left">
265	          <button
266	            type="button"
267	            onClick={() => setMode('list')}
268	            className="inline-flex items-center gap-1 text-xs font-mono text-[#8c7a9e] hover:text-[#ffd86b] transition cursor-pointer mb-1"
269	          >
270	            <ArrowLeft className="w-3.5 h-3.5" />
271	            <span>Back to Playlists List</span>
272	          </button>
273	
274	          {errorMessage && (
275	            <div className="p-2.5 rounded-lg bg-rose-950/80 border border-rose-600/70 text-rose-200 text-xs font-mono">
276	              ⚠️ {errorMessage}
277	            </div>
278	          )}
279	
280	          {/* Name & Emoji */}
281	          <div className="grid grid-cols-1 sm:grid-cols-4 gap-2.5">
282	            <div className="sm:col-span-3 space-y-1">
283	              <label className="text-xs font-mono text-[#8c7a9e]">Playlist Title *</label>
284	              <input
285	                type="text"
286	                autoFocus
287	                placeholder="e.g. Epic Battle Orchestral"
288	                value={name}
289	                onChange={(e) => setName(e.target.value)}
290	                className="w-full bg-[#171320] border border-[#3b2b4d] focus:border-[#ffd86b] rounded-xl px-3 py-2 text-sm text-white focus:outline-none transition"
291	              />
292	            </div>
293	
294	            <div className="space-y-1">
295	              <label className="text-xs font-mono text-[#8c7a9e]">Icon Emoji</label>
296	              <div className="flex items-center gap-1">
297	                <input
298	                  type="text"
299	                  maxLength={2}
300	                  value={emoji}
301	                  onChange={(e) => setEmoji(e.target.value)}
302	                  className="w-14 text-center bg-[#171320] border border-[#3b2b4d] focus:border-[#ffd86b] rounded-xl py-2 text-lg text-white focus:outline-none transition"
303	                />
304	              </div>
305	            </div>
306	          </div>
307	
308	          {/* Preset Emojis Row */}
309	          <div className="flex flex-wrap items-center gap-1.5">
310	            <span className="text-[10px] font-mono text-[#8c7a9e] mr-1">Quick Icons:</span>
311	            {PRESET_EMOJIS.map((em) => (
312	              <button
313	                key={em}
314	                type="button"
315	                onClick={() => setEmoji(em)}
316	                className={`w-7 h-7 rounded-lg text-sm flex items-center justify-center transition border cursor-pointer ${
317	                  emoji === em ? 'bg-[#ffd86b] border-[#ffd86b] text-black shadow-gold-sm' : 'bg-[#181224] border-[#312340] hover:bg-[#251b36]'
318	                }`}
319	              >
320	                {em}
321	              </button>
322	            ))}
323	          </div>
324	
325	          {/* Channel Multi-Selection Section */}
326	          <div className="p-3.5 rounded-xl bg-[#110d1a] border border-[#2b2038] space-y-2.5">
327	            <div className="flex items-center justify-between">
328	              <span className="text-xs font-cinzel font-bold text-[#ffd86b] flex items-center gap-1.5">
329	                <Radio className="w-3.5 h-3.5" />
330	                <span>Select Member Channels *</span>
331	              </span>
332	              <span className="text-[11px] font-mono text-[#8c7a9e]">
333	                <strong className="text-white">{selectedChannels.length}</strong> selected •{' '}
334	                <strong className="text-[#ffd86b]">{totalTracksInSelection.toLocaleString()}</strong> pooled songs
335	              </span>
336	            </div>
337	
338	            {/* Channel Searcher */}
339	            <div className="relative">
340	              <Search className="w-3.5 h-3.5 text-[#8c7a9e] absolute left-3 top-1/2 -translate-y-1/2" />
341	              <input
342	                type="text"
343	                placeholder="Filter channels (e.g. Hoyo, NCS, Remix)..."
344	                value={channelSearchQuery}
345	                onChange={(e) => setChannelSearchQuery(e.target.value)}
346	                className="w-full bg-[#181224] border border-[#362747] focus:border-[#d4af37] rounded-lg pl-9 pr-3 py-1.5 text-xs text-white focus:outline-none transition placeholder-[#5e4f73]"
347	              />
348	            </div>
349	
350	            {/* Channels Checklist */}
351	            <div className="max-h-44 overflow-y-auto space-y-1 pr-1">
352	              {filteredChannels.length === 0 ? (
353	                <p className="text-xs text-[#6e5d85] italic p-2">No matching channels found</p>
354	              ) : (
355	                filteredChannels.map((ch) => {
356	                  const isChecked = selectedChannels.includes(ch.name);
357	                  return (
358	                    <button
359	                      key={ch.name}
360	                      type="button"
361	                      onClick={() => toggleChannel(ch.name)}
362	                      className={`w-full flex items-center justify-between p-2 rounded-lg text-xs font-mono transition text-left cursor-pointer border ${
363	                        isChecked
364	                          ? 'bg-[#291e0a] text-[#ffd86b] border-[#d4af37] shadow-gold-sm'
365	                          : 'bg-[#181224] text-[#b3a6c7] hover:text-white border-[#2b1f3b] hover:bg-[#201830]'
366	                      }`}
367	                    >
368	                      <div className="flex items-center gap-2 truncate">
369	                        {isChecked ? (
370	                          <CheckSquare className="w-4 h-4 text-[#ffd86b] flex-shrink-0" />
371	                        ) : (
372	                          <Square className="w-4 h-4 text-[#6e5d85] flex-shrink-0" />
373	                        )}
374	                        <span className="truncate">{ch.name}</span>
375	                      </div>
376	                      <span className="text-[10px] text-[#8c7a9e] flex-shrink-0 ml-2">
377	                        {ch.count.toLocaleString()} songs
378	                      </span>
379	                    </button>
380	                  );
381	                })
382	              )}
383	            </div>
384	          </div>
385	
386	          {/* Compatible Timeblock Arcs */}
387	          <div className="p-3.5 rounded-xl bg-[#110d1a] border border-[#2b2038] space-y-2">
388	            <span className="text-xs font-cinzel font-bold text-[#ffd86b] flex items-center gap-1.5">
389	              <Layers className="w-3.5 h-3.5" />
390	              <span>Compatible Timeblock Arcs (Optional)</span>
391	            </span>
392	            <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
393	              {TIMEBLOCK_OPTIONS.map((tb) => {
394	                const isActive = selectedTimeblocks.includes(tb.id);
395	                return (
396	                  <button
397	                    key={tb.id}
398	                    type="button"
399	                    onClick={() => toggleTimeblock(tb.id)}
400	                    className={`p-2 rounded-lg text-xs font-sans flex items-center gap-2 transition border cursor-pointer ${
401	                      isActive
402	                        ? 'bg-[#291e0a] text-[#ffd86b] border-[#d4af37] shadow-gold-sm'
403	                        : 'bg-[#181224] text-[#8c7a9e] hover:text-white border-[#2b1f3b]'
404	                    }`}
405	                  >
406	                    <span>{tb.emoji}</span>
407	                    <span className="truncate text-[11px]">{tb.label}</span>
408	                    {isActive && <Check className="w-3.5 h-3.5 text-[#ffd86b] ml-auto flex-shrink-0" />}
409	                  </button>
410	                );
411	              })}
412	            </div>
413	          </div>
414	
415	          {/* Footer Actions */}
416	          <div className="flex items-center justify-end gap-2 pt-2 border-t border-[#261c33]">
417	            <SharedButton variant="secondary" size="md" onClick={() => setMode('list')} disabled={isSaving}>
418	              Cancel
419	            </SharedButton>
420	            <SharedButton variant="primary" size="md" onClick={handleSave} disabled={isSaving}>
421	              {isSaving ? 'Saving...' : editingPlaylistId ? 'Update Playlist' : 'Create Playlist'}
422	            </SharedButton>
423	          </div>
424	        </div>
425	      )}
426	    </ModalContainer>
427	  );
428	};
