19	export const ARC_METADATA: Record<string, { title: string; emoji: string }> = {
20	  timeblock_arc0: { title: 'Arc Zero ~ Kick Starter', emoji: '🌊' },
21	  timeblock_arc1: { title: 'Arc 01 ~ Morning Star - Raye', emoji: '🚀' },
22	  timeblock_arc2: { title: 'Arc 02 ~ Battle Phase - Racheal', emoji: '⚔️' },
23	  timeblock_arc3: { title: 'Arc 03 ~ Night Hours Melody', emoji: '🌙' },
24	  timeblock_arc4: { title: 'Arc 04 ~ Sacred Pragma', emoji: '🪶' },
25	};
