45	export function calculateHazardLevel(record: Tier3StateRecord | ChannelStateRecord): number {
46	  const rank = record.hazard_rank;
47	  if (!rank || rank < 3 || rank > 7) {
48	    return 3.0;
49	  }
50	
51	  const s5 = record.score_5_count?.length || 0;
52	  const s6 = record.score_6_count?.length || 0;
53	  const s7 = record.score_7_count?.length || 0;
54	
55	  // Sovereign calibration: 25 of 7+ (4pts), 50 of 6+ (2pts), or 100 of 5+ (1pt) to reach 8.0
56	  const S = 4 * s7 + 2 * s6 + 1 * s5;
57	
58	  const base = rank - 0.5;
59	  const k = (8.5 - rank) / 100.0;
60	
61	  const score = base + k * S;
62	  return Math.round(Math.min(8.5, Math.max(1.0, score)) * 100) / 100;
63	}
64	
65	export function calculateTotalPlayed(record: Tier3StateRecord | ChannelStateRecord): number {
66	  return (
67	    record.score_3_count.length +
68	    record.score_4_count.length +
69	    record.score_5_count.length +
70	    record.score_6_count.length +
71	    record.score_7_count.length
72	  );
73	}
74	
75	export function getDominantTimeblock(record: Tier3StateRecord | ChannelStateRecord): string | null {
76	  const arcCounts = [
77	    { key: 'timeblock_arc0', count: record.timeblock_arc0 },
78	    { key: 'timeblock_arc1', count: record.timeblock_arc1 },
79	    { key: 'timeblock_arc2', count: record.timeblock_arc2 },
80	    { key: 'timeblock_arc3', count: record.timeblock_arc3 },
81	    { key: 'timeblock_arc4', count: record.timeblock_arc4 },
82	  ];
83	  arcCounts.sort((a, b) => b.count - a.count);
84	  const highest = arcCounts[0];
85	  return highest && highest.count > 0 ? ARC_METADATA[highest.key]?.title || null : null;
86	}
87	
88	function parseJsonArray(val: unknown): string[] {
89	  if (Array.isArray(val)) return val;
90	  if (typeof val === 'string' && val.trim() !== '') {
91	    try {
92	      const parsed = JSON.parse(val);
93	      return Array.isArray(parsed) ? parsed : [];
94	    } catch {
95	      return [];
96	    }
97	  }
98	  return [];
99	}
