101	export async function fetchChannelState(
102	  projectId: string
103	): Promise<Record<string, ChannelStateRecord>> {
104	  try {
105	    const res = await executeOrder<Record<string, Record<string, unknown>>>({
106	      project_id: projectId,
107	      tier: 'channel_state',
108	      order: { action: 'read_all' },
109	    });
110	    const rawData = res.data || {};
111	    const result: Record<string, ChannelStateRecord> = {};
112	
113	    for (const [chId, row] of Object.entries(rawData)) {
114	      result[chId] = {
115	        channel_id: chId,
116	        channel_name: (row.channel_name as string) || '',
117	        score_3_count: parseJsonArray(row.score_3_count),
118	        score_4_count: parseJsonArray(row.score_4_count),
119	        score_5_count: parseJsonArray(row.score_5_count),
120	        score_6_count: parseJsonArray(row.score_6_count),
121	        score_7_count: parseJsonArray(row.score_7_count),
122	        timeblock_arc0: Number(row.timeblock_arc0) || 0,
123	        timeblock_arc1: Number(row.timeblock_arc1) || 0,
124	        timeblock_arc2: Number(row.timeblock_arc2) || 0,
125	        timeblock_arc3: Number(row.timeblock_arc3) || 0,
126	        timeblock_arc4: Number(row.timeblock_arc4) || 0,
127	        unlock_date: (row.unlock_date as string) || null,
128	        updated_at: (row.updated_at as string) || undefined,
129	      };
130	    }
131	    return result;
132	  } catch (e) {
133	    console.warn('[Engine] Failed to fetch channel_state table:', e);
134	    return {};
135	  }
136	}
