138	export async function rateChannelDirect(
139	  projectId: string,
140	  channelId: string,
141	  channelName: string,
142	  action: string,
143	  timeblocks: string[] = []
144	): Promise<{ success: boolean; hazard: number; played: number; record: ChannelStateRecord }> {
145	  const currentChannels = await fetchChannelState(projectId);
146	  const chRecord: ChannelStateRecord = currentChannels[channelId] || {
147	    channel_id: channelId,
148	    channel_name: channelName,
149	    score_3_count: [],
150	    score_4_count: [],
151	    score_5_count: [],
152	    score_6_count: [],
153	    score_7_count: [],
154	    timeblock_arc0: 0,
155	    timeblock_arc1: 0,
156	    timeblock_arc2: 0,
157	    timeblock_arc3: 0,
158	    timeblock_arc4: 0,
159	    unlock_date: null,
160	  };
161	
162	  const timestampHex = Date.now().toString(16).toUpperCase();
163	  const act = action.toLowerCase().trim();
164	
165	  if (act === '3+' || act === 'cancel' || act === 'downvote') {
166	    chRecord.score_3_count.push(timestampHex);
167	  } else if (act === '4+') {
168	    chRecord.score_4_count.push(timestampHex);
169	  } else if (act === '5+' || act === 'continue') {
170	    chRecord.score_5_count.push(timestampHex);
171	  } else if (act === '6+' || act === 'upvote') {
172	    chRecord.score_6_count.push(timestampHex);
173	  } else if (act === '7+' || act === 'overflow') {
174	    chRecord.score_7_count.push(timestampHex);
175	  }
176	
177	  if (timeblocks && timeblocks.length > 0) {
178	    timeblocks.forEach((b) => {
179	      if (/arc\s*zero|kick/i.test(b)) chRecord.timeblock_arc0++;
180	      else if (/arc\s*0?1|morning/i.test(b)) chRecord.timeblock_arc1++;
181	      else if (/arc\s*0?2|battle/i.test(b)) chRecord.timeblock_arc2++;
182	      else if (/arc\s*0?3|night/i.test(b)) chRecord.timeblock_arc3++;
183	      else if (/arc\s*0?4|sacred/i.test(b)) chRecord.timeblock_arc4++;
184	    });
185	  }
186	
187	  chRecord.updated_at = new Date().toISOString();
188	
189	  // 1. Upsert into channel_state table in _3_state.db
190	  await executeOrder({
191	    project_id: projectId,
192	    tier: 'channel_state',
193	    order: {
194	      action: 'upsert',
195	      key: channelId,
196	      data: {
197	        channel_name: channelName,
198	        score_3_count: JSON.stringify(chRecord.score_3_count),
199	        score_4_count: JSON.stringify(chRecord.score_4_count),
200	        score_5_count: JSON.stringify(chRecord.score_5_count),
201	        score_6_count: JSON.stringify(chRecord.score_6_count),
202	        score_7_count: JSON.stringify(chRecord.score_7_count),
203	        timeblock_arc0: chRecord.timeblock_arc0,
204	        timeblock_arc1: chRecord.timeblock_arc1,
205	        timeblock_arc2: chRecord.timeblock_arc2,
206	        timeblock_arc3: chRecord.timeblock_arc3,
207	        timeblock_arc4: chRecord.timeblock_arc4,
208	        unlock_date: chRecord.unlock_date,
209	        updated_at: chRecord.updated_at,
210	      },
211	    },
212	  });
213	
214	  // 2. Also record to Tier 2 JSONL event buffer
215	  await executeOrder({
216	    project_id: projectId,
217	    tier: '2',
218	    order: {
219	      action: 'append',
220	      data: {
221	        id: channelId,
222	        target_type: 'channel',
223	        channel_id: channelId,
224	        channel_name: channelName,
225	        action: action,
226	        timestamp: timestampHex,
227	        timeblock: timeblocks.length === 1 ? timeblocks[0] : timeblocks.length > 1 ? timeblocks : undefined,
228	      },
229	    },
230	  });
231	
232	  const hazard = calculateHazardLevel(chRecord);
233	  const played = calculateTotalPlayed(chRecord);
234	
235	  return { success: true, hazard, played, record: chRecord };
236	}
