238	export async function fetchEligibleTier4List(
239	  projectId: string,
240	  forceRefresh = false
241	): Promise<VinylDisplayCard[]> {
242	  if (!forceRefresh && cachedEligibleTier4List) {
243	    return cachedEligibleTier4List;
244	  }
245	
246	  const t4Res = await executeOrder<Record<string, Record<string, unknown>>>({
247	    project_id: projectId,
