259	    const hazard =
260	      rawHazard !== undefined && rawHazard !== null && !isNaN(Number(rawHazard))
261	        ? Number(rawHazard)
262	        : 3.0;
263	
264	    if (hazard <= 3.0) continue;
265	
266	    const rawPlayed = t4Item.played;
267	    const played =
268	      rawPlayed !== undefined && rawPlayed !== null && !isNaN(Number(rawPlayed))
269	        ? Number(rawPlayed)
270	        : 0;
271	
272	    list.push({
273	      id,
274	      dbIndex: indexCounter++,
275	      title: `Track ${id}`,
276	      channel: '',
277	      duration: null,
278	      hazard_level: hazard,
279	      played,
280	      timeblock: (t4Item.timeblock as string) || null,
281	      unlock_date: (t4Item.unlock_date as string) || null,
