290	// =============================================================================
291	// [FULL CATALOG SEARCH (ALL 173K+ TRACKS FROM _1_STATIC.DB)]
292	// Searches by title, channel, or ID across the entire static catalog
293	// =============================================================================
294	export async function searchFullCatalog(
295	  projectId: string,
296	  query: string,
297	  limit = 30
298	): Promise<VinylDisplayCard[]> {
299	  if (!query || query.trim().length < 2) return [];
300	
301	  const [searchRes, t4Res] = await Promise.all([
302	    executeOrder<Record<string, Record<string, unknown>>>({
303	      project_id: projectId,
304	      tier: '1',
305	      order: { action: 'sample', data: { search: query.trim(), limit } },
306	    }),
307	    executeOrder<Record<string, Record<string, unknown>>>({
308	      project_id: projectId,
309	      tier: '4',
310	      order: { action: 'read_all' },
311	    }),
312	  ]);
313	
314	  const rawData = searchRes.data || {};
315	  const t4Data = t4Res.data || {};
316	  const list: VinylDisplayCard[] = [];
317	  let indexCounter = 1;
318	
319	  for (const [id, row] of Object.entries(rawData)) {
320	    const v = (row as Record<string, unknown>) || {};
321	    const t4Item = t4Data[id] as Record<string, unknown> | undefined;
322	    const hazard = t4Item?.hazard_level !== undefined && t4Item?.hazard_level !== null
323	      ? Number(t4Item.hazard_level)
324	      : 3.0;
325	    const played = t4Item?.played !== undefined && t4Item?.played !== null
326	      ? Number(t4Item.played)
327	      : 0;
328	
329	    list.push({
330	      id,
331	      dbIndex: indexCounter++,
332	      title: (v.title as string) || `Track ${id}`,
333	      channel:
334	        (v.channel_name as string) ||
335	        (v.channel as string) ||
336	        (v.artist as string) ||
337	        'Unknown Origin',
338	      duration: (v.duration as number) ?? null,
339	      hazard_level: Math.round(hazard * 100) / 100,
340	      played,
341	      timeblock: (t4Item?.timeblock as string) || null,
342	      unlock_date: (t4Item?.unlock_date as string) || null,
343	      rankCategory: getRankFromScore(hazard),
344	    });
345	  }
346	
347	  return list;
348	}
