353	export async function resolvePageMetadataOnDemand(
354	  projectId: string,
355	  pageTracks: VinylDisplayCard[]
356	): Promise<VinylDisplayCard[]> {
357	  if (pageTracks.length === 0) return [];
358	
359	  const missingIds = pageTracks
360	    .map((t) => t.id)
361	    .filter((id) => !tier1MemoryCache[id]);
362	
363	  if (missingIds.length > 0) {
364	    try {
365	      const res = await executeOrder<Record<string, Tier1StaticItem>>({
366	        project_id: projectId,
367	        tier: '1',
368	        order: { action: 'batch_read', data: missingIds },
369	      });
370	      const dataMap = res.data || {};
371	      for (const [id, staticInfo] of Object.entries(dataMap)) {
372	        tier1MemoryCache[id] = staticInfo;
373	      }
374	    } catch (e) {
375	      console.warn(`[LazyTier1 Batch] Lỗi tải batch ${missingIds.length} items:`, e);
376	    }
377	  }
378	
379	  return pageTracks.map((item) => {
380	    const staticInfo = tier1MemoryCache[item.id];
381	    return {
382	      ...item,
383	      title: staticInfo?.title || item.title,
384	      channel:
385	        staticInfo?.channel_name ||
386	        staticInfo?.channel ||
387	        staticInfo?.artist ||
388	        'Unknown Origin',
389	      duration: staticInfo?.duration ?? null,
390	    };
391	  });
392	}
