433	export async function syncTier2ToTier3(projectId: string) {
434	  const tier2Res = await executeOrder<Tier2EventEntry[]>({
435	    project_id: projectId,
436	    tier: '2',
437	    order: { action: 'read_all' },
438	  });
439	  const rawEvents = Array.isArray(tier2Res.data) ? tier2Res.data : [];
440	
441	  // 1. Gather all block events from rawEvents
442	  const blockedIds: string[] = [];
443	  for (const evt of rawEvents) {
444	    if (!evt || !evt.id) continue;
445	    const act = (evt.action || '').toLowerCase().trim();
446	    if (act === 'block') {
447	      blockedIds.push(evt.id);
448	    }
449	  }
450	
451	  // 2. Directly purge any block events from Tier 1 (cascades to Tier 3, Tier 4, and system dbs)
452	  if (blockedIds.length > 0) {
453	    await executeOrder({
454	      project_id: projectId,
455	      tier: '1',
456	      order: {
457	        action: 'batch_delete',
458	        data: blockedIds,
459	      },
460	    });
461	    blockedIds.forEach((id) => delete tier1MemoryCache[id]);
462	    invalidateVinylCache(projectId);
463	  }
464	
465	  // 3. Process non-blocked rating events for Tier 3 tracks and channels
466	  const excludedSet = new Set(blockedIds);
467	  const [currentT3, currentChannels] = await Promise.all([
468	    fetchTier3State(projectId),
469	    fetchChannelState(projectId),
470	  ]);
471	
472	  const stateMap: Record<string, Tier3StateRecord> = {};
473	  currentT3.forEach((r) => {
474	    if (!excludedSet.has(r.id)) {
475	      stateMap[r.id] = r;
476	    }
477	  });
478	
479	  const channelMap: Record<string, ChannelStateRecord> = { ...currentChannels };
480	  const modifiedTrackIds = new Set<string>();
481	  const modifiedChannelIds = new Set<string>();
482	
483	  for (const evt of rawEvents) {
484	    if (!evt || !evt.id || excludedSet.has(evt.id)) continue;
485	    const act = (evt.action || '').toLowerCase().trim();
486	    if (act === 'block') continue;
487	
488	    // Check if event is targeted to an entire channel
489	    if (evt.target_type === 'channel' || (evt.channel_id && evt.channel_id === evt.id)) {
490	      const chId = evt.channel_id || evt.id;
491	      if (!channelMap[chId]) {
492	        channelMap[chId] = {
493	          channel_id: chId,
494	          channel_name: evt.channel_name || '',
495	          score_3_count: [],
496	          score_4_count: [],
497	          score_5_count: [],
498	          score_6_count: [],
499	          score_7_count: [],
500	          timeblock_arc0: 0,
501	          timeblock_arc1: 0,
502	          timeblock_arc2: 0,
503	          timeblock_arc3: 0,
504	          timeblock_arc4: 0,
505	          unlock_date: null,
506	        };
507	      }
508	      const ch = channelMap[chId];
509	      if (evt.hazard_rank !== undefined && evt.hazard_rank !== null) {
510	        (ch as any).hazard_rank = Number(evt.hazard_rank);
511	      }
512	
513	      if (act === '3+' || act === 'cancel' || act === 'downvote') {
514	        ch.score_3_count.push(evt.timestamp);
515	      } else if (act === '4+') {
516	        ch.score_4_count.push(evt.timestamp);
517	      } else if (act === '5+' || act === 'continue') {
518	        ch.score_5_count.push(evt.timestamp);
519	      } else if (act === '6+' || act === 'upvote') {
520	        ch.score_6_count.push(evt.timestamp);
521	      } else if (act === '7+' || act === 'overflow') {
522	        ch.score_7_count.push(evt.timestamp);
523	      }
524	
525	      if (evt.timeblock) {
526	        const blocks = Array.isArray(evt.timeblock) ? evt.timeblock : [evt.timeblock];
527	        blocks.forEach((b) => {
528	          if (/arc\s*zero|kick/i.test(b)) ch.timeblock_arc0++;
529	          else if (/arc\s*0?1|morning/i.test(b)) ch.timeblock_arc1++;
530	          else if (/arc\s*0?2|battle/i.test(b)) ch.timeblock_arc2++;
531	          else if (/arc\s*0?3|night/i.test(b)) ch.timeblock_arc3++;
532	          else if (/arc\s*0?4|sacred/i.test(b)) ch.timeblock_arc4++;
533	        });
534	      }
535	      modifiedChannelIds.add(chId);
536	      continue;
537	    }
538	
539	    // Otherwise it's a track-level event
540	    if (!stateMap[evt.id]) {
541	      stateMap[evt.id] = {
542	        id: evt.id,
543	        score_3_count: [],
544	        score_4_count: [],
545	        score_5_count: [],
546	        score_6_count: [],
547	        score_7_count: [],
548	        timeblock_arc0: 0,
549	        timeblock_arc1: 0,
550	        timeblock_arc2: 0,
551	        timeblock_arc3: 0,
552	        timeblock_arc4: 0,
553	        unlock_date: null,
554	        hazard_rank: null,
555	      };
556	    }
557	    const r = stateMap[evt.id];
558	    if (evt.hazard_rank !== undefined && evt.hazard_rank !== null) {
559	      r.hazard_rank = Number(evt.hazard_rank);
560	    }
561	
562	    if (act === '3+' || act === 'cancel' || act === 'downvote') {
563	      r.score_3_count.push(evt.timestamp);
564	    } else if (act === '4+') {
565	      r.score_4_count.push(evt.timestamp);
566	    } else if (act === '5+' || act === 'continue') {
567	      r.score_5_count.push(evt.timestamp);
568	    } else if (act === '6+' || act === 'upvote') {
569	      r.score_6_count.push(evt.timestamp);
570	    } else if (act === '7+' || act === 'overflow') {
571	      r.score_7_count.push(evt.timestamp);
572	    }
573	
574	    if (evt.timeblock) {
575	      const blocks = Array.isArray(evt.timeblock) ? evt.timeblock : [evt.timeblock];
576	      blocks.forEach((b) => {
577	        if (/arc\s*zero|kick/i.test(b)) r.timeblock_arc0++;
578	        else if (/arc\s*0?1|morning/i.test(b)) r.timeblock_arc1++;
579	        else if (/arc\s*0?2|battle/i.test(b)) r.timeblock_arc2++;
580	        else if (/arc\s*0?3|night/i.test(b)) r.timeblock_arc3++;
581	        else if (/arc\s*0?4|sacred/i.test(b)) r.timeblock_arc4++;
582	      });
583	    }
584	    modifiedTrackIds.add(evt.id);
585	  }
586	
587	  // 7. Upsert modified track states into tier_3_data
588	  if (modifiedTrackIds.size > 0) {
589	    const t3BatchData: Record<string, Record<string, unknown>> = {};
590	    for (const id of modifiedTrackIds) {
591	      if (excludedSet.has(id)) continue;
592	      const r = stateMap[id];
593	      t3BatchData[id] = {
594	        score_3_count: JSON.stringify(r.score_3_count),
595	        score_4_count: JSON.stringify(r.score_4_count),
596	        score_5_count: JSON.stringify(r.score_5_count),
597	        score_6_count: JSON.stringify(r.score_6_count),
598	        score_7_count: JSON.stringify(r.score_7_count),
599	        timeblock_arc0: r.timeblock_arc0,
600	        timeblock_arc1: r.timeblock_arc1,
601	        timeblock_arc2: r.timeblock_arc2,
602	        timeblock_arc3: r.timeblock_arc3,
603	        timeblock_arc4: r.timeblock_arc4,
604	        unlock_date: r.unlock_date,
605	        hazard_rank: r.hazard_rank ?? null,
606	      };
607	    }
608	
609	    await executeOrder({
610	      project_id: projectId,
611	      tier: '3',
612	      order: {
613	        action: 'batch_upsert',
614	        data: t3BatchData,
615	      },
616	    });
617	  }
618	
619	  // 8. Upsert modified channel states into channel_state table
620	  if (modifiedChannelIds.size > 0) {
621	    const chBatchData: Record<string, Record<string, unknown>> = {};
622	    for (const chId of modifiedChannelIds) {
623	      const ch = channelMap[chId];
624	      chBatchData[chId] = {
625	        channel_id: ch.channel_id,
626	        channel_name: ch.channel_name,
627	        score_3_count: JSON.stringify(ch.score_3_count),
628	        score_4_count: JSON.stringify(ch.score_4_count),
629	        score_5_count: JSON.stringify(ch.score_5_count),
630	        score_6_count: JSON.stringify(ch.score_6_count),
631	        score_7_count: JSON.stringify(ch.score_7_count),
632	        timeblock_arc0: ch.timeblock_arc0,
633	        timeblock_arc1: ch.timeblock_arc1,
634	        timeblock_arc2: ch.timeblock_arc2,
635	        timeblock_arc3: ch.timeblock_arc3,
636	        timeblock_arc4: ch.timeblock_arc4,
637	        unlock_date: ch.unlock_date,
638	        updated_at: new Date().toISOString(),
639	      };
640	    }
641	
642	    await executeOrder({
643	      project_id: projectId,
644	      tier: 'channel_state',
645	      order: {
646	        action: 'batch_upsert',
647	        data: chBatchData,
648	      },
649	    });
650	  }
651	
652	  // Only clear _2_events.jsonl when buffer exceeds 15 events (prevents excessive API calls)
653	  if (rawEvents.length >= 15) {
654	    await executeOrder({ project_id: projectId, tier: '2', order: { action: 'clear' } });
655	  }
656	
657	  return {
658	    eventsProcessed: rawEvents.length,
659	    updatedTracksCount: modifiedTrackIds.size,
660	    updatedChannelsCount: modifiedChannelIds.size,
661	    blockedCount: blockedIds.length,
662	    staticSynced: true,
663	  };
664	}
