852	  hazardCap?: number | string | null,
853	  excludeChannel?: string | string[] | null,
854	  channels?: string[] | null,
855	  blockedIds?: string[] | null  // NEW: immediately excluded blocked song IDs
856	): Promise<{
857	  tracks: PlaylistItem[];
858	  totalCatalogCount: number;
859	  statsMap: Record<string, import('../types').TrackDisplayMeta>;
860	}> {
861	  const samplePayload: any = { limit };
862	  if (channels && channels.length > 0) {
863	    samplePayload.channels = channels;
864	  } else if (channelName && channelName !== 'ALL') {
865	    samplePayload.channel_name = channelName;
866	  }
867	  if (excludeChannel && excludeChannel !== 'NONE' && excludeChannel !== 'ALL') {
868	    samplePayload.exclude_channel = excludeChannel;
869	  }
870	  if (hazardCap !== undefined && hazardCap !== null && hazardCap !== 'ALL' && hazardCap !== 'NONE') {
871	    samplePayload.hazard_cap = hazardCap;
872	  }
873	  // NEW: Pass blocked song IDs for immediate exclusion from pool
874	  if (blockedIds && blockedIds.length > 0) {
875	    samplePayload.exclude_ids = blockedIds;
