1254	export async function streamPlaylistIngestion(
1255	  options: {
1256	    urls?: string[];
1257	    max_playlists?: number;
1258	    max_per_playlist?: number;
1259	  },
1260	  onEvent: (event: CurlerStreamEvent) => void,
1261	  signal?: AbortSignal
1262	): Promise<void> {
1263	  const res = await fetch(`${API_BASE}/api/v1/curler/stream`, {
1264	    method: 'POST',
1265	    headers: { 'Content-Type': 'application/json' },
1266	    body: JSON.stringify(options),
1267	    signal,
1268	  });
1269	
1270	  if (!res.ok) {
1271	    throw new Error(`Curler stream request failed with HTTP ${res.status}`);
1272	  }
1273	
1274	  if (!res.body) {
1275	    throw new Error('ReadableStream not supported on response body.');
1276	  }
1277	
1278	  const reader = res.body.getReader();
1279	  const decoder = new TextDecoder('utf-8');
1280	  let buffer = '';
1281	
1282	  while (true) {
1283	    const { done, value } = await reader.read();
1284	    if (done) break;
1285	
1286	    buffer += decoder.decode(value, { stream: true });
1287	    const chunks = buffer.split('\n\n');
1288	    buffer = chunks.pop() || '';
1289	
1290	    for (const chunk of chunks) {
1291	      const trimmed = chunk.trim();
1292	      if (trimmed.startsWith('data:')) {
1293	        try {
1294	          const jsonStr = trimmed.slice(5).trim();
1295	          if (jsonStr) {
1296	            const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1297	            onEvent(eventData);
1298	          }
1299	        } catch (err) {
1300	          console.warn('[Curler Stream] Failed to parse SSE chunk:', err);
1301	        }
1302	      }
1303	    }
1304	  }
1305	
1306	  if (buffer.trim().startsWith('data:')) {
1307	    try {
1308	      const jsonStr = buffer.trim().slice(5).trim();
1309	      if (jsonStr) {
1310	        const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1311	        onEvent(eventData);
1312	      }
1313	    } catch (_) {}
1314	  }
1315	
1316	  // Clear static caches after streaming completes
1317	  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
1318	  invalidateVinylCache();
1319	}
