678	                          className="flex items-center gap-1 px-2.5 py-1 text-xs"
679	                        >
680	                          <Play className="w-3 h-3 fill-[#ffd86b] text-[#ffd86b]" />
681	                          <span>Stream</span>
682	                        </SharedButton>
683	
684	                        <button
685	                          type="button"
686	                          disabled={purgingChannelName === ch.name}
687	                          onClick={(e) => handlePurgeChannel(ch, e)}
688	                          title={`Purge all ${ch.count} songs of "${ch.name}" to re-curl clean`}
689	                          className="p-1.5 rounded-lg bg-rose-950/40 hover:bg-rose-900/60 border border-rose-800/50 text-rose-300 hover:text-rose-100 transition cursor-pointer disabled:opacity-50"
690	                        >
691	                          <Trash2
692	                            className={`w-3.5 h-3.5 ${
693	                              purgingChannelName === ch.name ? 'animate-spin' : ''
694	                            }`}
695	                          />
696	                        </button>
697	                      </div>
698	                    </div>
699	                  </div>
700	                );
701	              })}
702	            </div>
703	          )}
704	        </div>
705	      )}
706	
707	      {/* Playlist Manager Modal */}
708	      <PlaylistManagerModal
709	        isOpen={isModalOpen}
710	        onClose={() => setIsModalOpen(false)}
711	        projectId={targetProjectId}
712	        channelList={channelList}
713	        initialEditPlaylistId={editPlaylistId}
714	        onSelectPlaylist={(plId) => {
715	          setIsModalOpen(false);
716	          handlePlaySource(`CUSTOM:${plId}`);
717	        }}
718	      />
719	    </div>
720	  );
721	};
