const handleDelete = async (plId: string) => {
  const playlist = customPlaylists.find((p) => p.id === plId);
  if (!playlist) return;

  const totalSongs = playlist.channels.reduce((sum, chName) => {
    const ch = channelList.find((c) => c.name === chName);
    return sum + (ch?.count || 0);
  }, 0);

  const confirmed = confirm(
    `⚠️ PLAYLIST DELETION & CHANNEL PURGE\n\n` +
    `Delete playlist "${playlist.name}" (${playlist.channels.length} channels, ${totalSongs.toLocaleString()} songs)?\n\n` +
    `This will:\n` +
    `1. Delete the playlist federation\n` +
    `2. PERMANENTLY PURGE all ${totalSongs.toLocaleString()} songs from these channels:\n` +
    `   ${playlist.channels.join(', ')}\n\n` +
    `This allows you to re-curl these channels with refined filters.\n\n` +
    `Proceed with deletion + purge?`
  );

  if (!confirmed) return;

  try {
    // Step 1: Purge all songs from member channels
    const purgePromises = playlist.channels.map(async (chName) => {
      const ch = channelList.find((c) => c.name === chName);
      if (ch) {
        try {
          await purgeChannelSongs(projectId, ch.name, ch.channel_id);
        } catch (err) {
          console.warn(`Failed to purge channel ${chName}:`, err);
        }
      }
    });

    await Promise.all(purgePromises);

    // Step 2: Delete the playlist itself
    await deleteCustomPlaylist(projectId, plId);
    removeCustomPlaylist(plId);

    if (mode === 'edit' && editingPlaylistId === plId) {
      setMode('list');
    }

    // Show success toast (if you have a toast system)
    if ((window as any).showToast) {
      (window as any).showToast(
        `✅ Deleted playlist "${playlist.name}" and purged ${totalSongs.toLocaleString()} songs from ${playlist.channels.length} channels`,
        'success'
      );
    }
  } catch (err) {
    console.error('Failed to delete playlist and purge channels:', err);
    if ((window as any).showToast) {
      (window as any).showToast(`Failed to delete playlist: ${err}`, 'error');
    }
  }
};

