const syncVideoToPlayer = useCallback((targetVideoId: string | null) => {
  if (!targetVideoId) return;

  if (!isPlayerReadyRef.current || !playerRef.current) {
    pendingVideoIdRef.current = targetVideoId;
    return;
  }

  if (currentlyLoadedVideoIdRef.current === targetVideoId) {
    return;
  }

  try {
    currentlyLoadedVideoIdRef.current = targetVideoId;
    pendingVideoIdRef.current = null;
    playerRef.current.loadVideoById({
      videoId: String(targetVideoId).trim(),
      startSeconds: 0,
    });
    playerRef.current.playVideo();
