      msg += ` (🚫 ${t2Res.blockedCount} blacklisted)`;
    }
    if (t3Res.purgedCount > 0) {
      msg += ` (☣️ ${t3Res.purgedCount} bad KPI purged)`;
    }
    setToast(msg);
    await loadData();
  } catch (e) {
    setToast(`❌ Error: ${e}`);
  } finally {
    setIsProcessing(false);
  }
};

